import{_ as a,o as t,c as o,a0 as d}from"./chunks/framework.D2qex3w9.js";const p=JSON.parse('{"title":"Proposal: Add Order Status Badge & Order Routing Modal","description":"","frontmatter":{},"headers":[],"relativePath":"changes/archive/2026-06-09-modal-add-order-status-badge/proposal.md","filePath":"changes/archive/2026-06-09-modal-add-order-status-badge/proposal.md"}'),i={name:"changes/archive/2026-06-09-modal-add-order-status-badge/proposal.md"};function r(l,e,s,c,n,u){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="proposal-add-order-status-badge-order-routing-modal" tabindex="-1">Proposal: Add Order Status Badge &amp; Order Routing Modal <a class="header-anchor" href="#proposal-add-order-status-badge-order-routing-modal" aria-label="Permalink to &quot;Proposal: Add Order Status Badge &amp; Order Routing Modal&quot;">​</a></h1><h2 id="intent" tabindex="-1">Intent <a class="header-anchor" href="#intent" aria-label="Permalink to &quot;Intent&quot;">​</a></h2><p>The auction orders table has an unused add button and displays order status as plain text. Users need a modal to route to different order types (Intervención, Mesa de cambio) and visual differentiation of statuses (en proceso, aprobada, rechazada) for quick scanability.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><h3 id="in-scope" tabindex="-1">In Scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In Scope&quot;">​</a></h3><ul><li>Add (click) handler to the existing add button to open a modal</li><li>Create <code>ModalCurrencyAddOrderComponent</code> in <code>src/app/features/shared/</code></li><li>Material select with routing: Intervención → <code>main/divisas/compra/intervencion</code>, Mesa de cambio - Compra → <code>main/divisas/compra/mesa-cambio</code>, Mesa de cambio - Venta → <code>main/divisas/venta/mesa-cambio</code></li><li>Status column visual badge (en proceso, aprobada, rechazada) using CSS variables from <code>styles.scss</code></li><li>Register modal in SharedModule; add to DivisasModule if needed</li></ul><h3 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>Backend changes to status field values or structure</li><li>Sorting/filtering changes to the generic table</li><li>Visual changes to other table columns</li></ul><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><h3 id="new-capabilities" tabindex="-1">New Capabilities <a class="header-anchor" href="#new-capabilities" aria-label="Permalink to &quot;New Capabilities&quot;">​</a></h3><ul><li><code>order-routing-modal</code>: Modal dialog for selecting and navigating to order creation pages</li><li><code>order-status-badge</code>: Visual chip/badge component for auction order status display</li></ul><h3 id="modified-capabilities" tabindex="-1">Modified Capabilities <a class="header-anchor" href="#modified-capabilities" aria-label="Permalink to &quot;Modified Capabilities&quot;">​</a></h3><ul><li>None</li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><ol><li><p><strong>Add button</strong>: Bind <code>(click)=&quot;openAddModal()&quot;</code> to existing <code>&lt;button mat-mini-fab&gt;</code> in the HTML template; implement <code>openAddModal()</code> in the component TS to call <code>MatDialog.open(ModalCurrencyAddOrderComponent)</code>.</p></li><li><p><strong>Modal</strong>: Create <code>src/app/features/shared/modal-currency-add-order/</code> with Angular Material <code>MatDialog</code>. SVG close button using <code>--color-principal</code> + hover lift animation. Label + <code>&lt;mat-select&gt;</code> with 3 options. On selection, <code>this.router.navigate([&#39;main/divisas/...&#39;])</code> then close dialog.</p></li><li><p><strong>Status badge</strong>: Custom CSS classes bound to the status value (using <code>[ngClass]</code> or a custom pipe). Map: &quot;en proceso&quot; → amber/warning (<code>--card-color: #7ab400</code>), &quot;aprobada&quot; → green success (<code>--color-principal: #62A730</code>), &quot;rechazada&quot; → red (<code>--color-rojo: #f83a40</code>). Apply as small rounded chips.</p></li></ol><h2 id="affected-areas" tabindex="-1">Affected Areas <a class="header-anchor" href="#affected-areas" aria-label="Permalink to &quot;Affected Areas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Impact</th><th>Description</th></tr></thead><tbody><tr><td><code>.../tabla-consulta-ordenes-subasta.component.ts</code></td><td>Modified</td><td>Add <code>openAddModal()</code> method, inject <code>MatDialog</code> + <code>Router</code></td></tr><tr><td><code>.../tabla-consulta-ordenes-subasta.component.html</code></td><td>Modified</td><td>Add (click) to add button</td></tr><tr><td><code>src/app/features/shared/modal-currency-add-order/</code></td><td>New</td><td>Modal component (ts, html, scss)</td></tr><tr><td><code>src/app/features/shared/shared.module.ts</code></td><td>Modified</td><td>Declare and export new modal component</td></tr><tr><td><code>src/app/features/shared/generic-table-without-actions/</code></td><td>Modified</td><td>Add status badge rendering logic</td></tr><tr><td><code>src/styles.scss</code></td><td>Possibly</td><td>New status badge utility classes if needed</td></tr></tbody></table><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Mitigation</th></tr></thead><tbody><tr><td>Status field name from backend may differ</td><td>Low</td><td>Use dynamic column key <code>status</code>, verify with API response</td></tr><tr><td>Routing paths change in future</td><td>Low</td><td>Hardcode paths per spec; trivial to update</td></tr></tbody></table><h2 id="rollback-plan" tabindex="-1">Rollback Plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback Plan&quot;">​</a></h2><ul><li>Revert changes to <code>tabla-consulta-ordenes-subasta.component.ts</code> and <code>.html</code></li><li>Delete <code>modal-currency-add-order/</code> directory</li><li>Remove declaration from <code>shared.module.ts</code></li><li>Revert <code>generic-table-without-actions</code> changes</li></ul><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li>Angular Material Dialog (<code>MatDialog</code>) already imported</li><li>RouterModule available in DivisasModule context</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] Clicking add button opens the modal with correct label and select options</li><li>[ ] Each select option navigates to the correct route and closes the modal</li><li>[ ] Status column shows colored badges (green/orange/red) instead of plain text</li><li>[ ] All styles use CSS variables from <code>styles.scss</code>, no hardcoded colors</li></ul>',25)])])}const b=a(i,[["render",r]]);export{p as __pageData,b as default};
